from typing import cast as CastValue

from interchange.geometry.Models.GeometryCurves import LineGeometry
from interchange.serialization.EncodeData import ToData
from tests.Convert.Solidworks.Research.Construction.Part.BlindCaseInput import (
    BlindCaseInput,
)
from tests.Convert.Solidworks.Research.Construction.RectDimensions.MakeRectDimDoc import (
    MakeRectDimDoc,
)


# distinct width height placement routing and provenance inputs must change generated bytes through the complete neutral document path
def RectDimRequest(NameValue: str, IsVariant: bool) -> dict[str, object]:
    RequestValue = BlindCaseInput(NameValue, IsVariant)
    DocumentValue = MakeRectDimDoc(NameValue, IsVariant)
    RequestValue["document"] = CastValue(object, ToData(DocumentValue))
    SettingsValue = CastValue(dict[str, object], RequestValue["settings"])
    SettingsValue["design_intent"] = IsVariant
    SettingsValue["selected_leader"] = 2 if IsVariant else 0
    SketchValue = DocumentValue.sketches[0]
    FirstLine = CastValue(LineGeometry, SketchValue.entities[0].geometry)
    SecondLine = CastValue(LineGeometry, SketchValue.entities[1].geometry)
    RequestValue["rectangle_dimensions"] = {
        "width_text_m": [
            (FirstLine.start.x * 0.65 + FirstLine.end.x * 0.35) * 0.001,
            FirstLine.start.y * 0.001 - 0.0067,
        ],
        "height_text_m": [
            SecondLine.start.x * 0.001 + 0.0082,
            (SecondLine.start.y * 0.39 + SecondLine.end.y * 0.61) * 0.001,
        ],
        "route_centerline": IsVariant,
    }
    return RequestValue
